entries[22568] = { ["name"] = "Wilder Biss", ["text"] = "25 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der pro Combopunkt Schaden verursacht [ Glyphe 'Wilder Biss' : bis zu 25 Energie zusätzlich verbraucht, um den verursachten Schaden um bis zu 100% zu erhöhen, und Euch pro 10 verbrauchter Energie um 2% Eurer gesamten Gesundheit heilt / und bis zu 25 Energie zusätzlich verbraucht, um den verursachten Schaden um bis zu 100% zu erhöhen.]\nWenn das Ziel über weniger als 25% Gesundheit verfügt, wird 'Wilder Biss' außerdem die Dauer Eures Effekts 'Zerfetzen' auf dem Ziel zurücksetzen.\n\nBei blutenden Zielen ist die kritische Trefferchance um 35% erhöht.\n\n1 Punkt: [(((((36 + (Angriffskraft * 0.196)))) * (( 1 * 1 * 1 ))) + 316 )] bis [(((((36 + (Angriffskraft * 0.196)))) * (( 1 * 1 * 1 ))) + 685 )] Schaden\n2 Punkte: [(((((36 + (Angriffskraft * 0.196))) * 2) * (( 1 * 1 * 1 ))) + 316 )] bis [(((((36 + (Angriffskraft * 0.196))) * 2) * (( 1 * 1 * 1 ))) + 685 )] Schaden\n3 Punkte: [(((((36 + (Angriffskraft * 0.196))) * 3) * (( 1 * 1 * 1 ))) + 316 )] bis [(((((36 + (Angriffskraft * 0.196))) * 3) * (( 1 * 1 * 1 ))) + 685 )] Schaden\n4 Punkte: [(((((36 + (Angriffskraft * 0.196))) * 4) * (( 1 * 1 * 1 ))) + 316 )] bis [(((((36 + (Angriffskraft * 0.196))) * 4) * (( 1 * 1 * 1 ))) + 685 )] Schaden\n5 Punkte: [(((((36 + (Angriffskraft * 0.196))) * 5) * (( 1 * 1 * 1 ))) + 316 )] bis [(((((36 + (Angriffskraft * 0.196))) * 5) * (( 1 * 1 * 1 ))) + 685 )] Schaden" }
entries[22570] = { ["name"] = "Zerfleddern", ["text"] = "35 Energie Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Katzengestalt\nFinishing-Move, der 200% Waffenschaden verursacht und das Ziel betäubt. Verursacht pro Combopunkt mehr Bonusschaden und hält länger an:\n\n1 Punkt: [ 2 * (Haupthandwaffen-Min-Schaden / 2 + 84 + 82 )] bis [ 2 * (Haupthandwaffen-Max-Schaden / 2 + 84 + 82 )] Schaden, 1 Sek.\n2 Punkte: [ 2 * (Haupthandwaffen-Min-Schaden / 2 + 84 * 2 + 82 )] bis [ 2 * (Haupthandwaffen-Max-Schaden / 2 + 84 * 2 + 82 )] Schaden, 2 Sek.\n3 Punkte: [ 2 * (Haupthandwaffen-Min-Schaden / 2 + 84 * 3 + 82 )] bis [ 2 * (Haupthandwaffen-Max-Schaden / 2 + 84 * 3 + 82 )] Schaden, 3 Sek.\n4 Punkte: [ 2 * (Haupthandwaffen-Min-Schaden / 2 + 84 * 4 + 82 )] bis [ 2 * (Haupthandwaffen-Max-Schaden / 2 + 84 * 4 + 82 )] Schaden, 4 Sek.\n5 Punkte: [ 2 * (Haupthandwaffen-Min-Schaden / 2 + 84 * 5 + 82 )] bis [ 2 * (Haupthandwaffen-Max-Schaden / 2 + 84 * 5 + 82 )] Schaden, 5 Sek." }
