entries[22906] = { ["name"] = "Ramme Klinge in Onyxia", ["text"] = "10 Meter Reichweite\nWirken in 3 sek.\nIns Herz der Brutmutter rammen, um die erhitzte Klinge zu härten." }
entries[22907] = { ["name"] = "Schießen", ["text"] = "5 - 30 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nSchießt auf den Gegner und verursacht körperlichen Schaden." }
entries[22908] = { ["name"] = "Salve", ["text"] = "5 - 30 Meter ReichweiteKanalisiert (Wirken in 6 sek.) 1 min Abklingzeit\nBenötigt Distanzwaffe\nFeuert kontinuierlich eine Salve Munition auf das Zielgebiet und verursacht 6 Sek. lang pro Sekunde 300 Arkanschaden bei feindlichen Zielen im Umkreis von 8 Metern." }
entries[22909] = { ["name"] = "Auge von Immol'thar", ["text"] = "Nahkampfreichweite\nWirken in 2 sek.\nDas Auge von Immol'thar richtet den Blick auf ein feindliches Ziel, wodurch sein Bewegungstempo um 40% und sein Zaubertempo um 50% verlangsamt sowie die Zeit zwischen seinen Nahkampfangriffen um 100% erhöht wird." }
entries[22910] = { ["name"] = "Feuerbrandfalle", ["text"] = "Sofort 15 sek. Abklingzeit\nEine Feuerfalle platzieren, die dem ersten sich nähernden Feind im Verlauf von 15 Sek. Feuerschaden zufügt. Die Falle besteht 1 Min. lang." }
entries[22911] = { ["name"] = "Sturmangriff", ["text"] = "8 - 25 Meter Reichweite\nSofort\nStürmt auf einen Gegner zu, verursacht Schaden und betäubt ihn 2 Sek. lang." }
entries[22912] = { ["name"] = "Blockwert 36", ["text"] = "Erhöht den Blockwert Eures Schildes um 36." }
entries[22914] = { ["name"] = "Erschütternder Schuss", ["text"] = "45 Meter Reichweite\nBenötigt Distanzwaffe\nMacht einen Feind benommen und verringert sein Bewegungstempo 3 Sek. lang um 50%." }
entries[22915] = { ["name"] = "Verbesserter erschütternder Schuss", ["text"] = "45 Meter Reichweite\nSofort\nBetäubt das Ziel 3 Sek. lang." }
entries[22916] = { ["name"] = "Aufwärtshaken", ["text"] = "10 Meter Reichweite\nSofort\nFügt einem Feind normalen Schaden plus 50 zu und stößt ihn zurück." }
entries[22917] = { ["name"] = "Schattengestalt", ["text"] = "40% von Grundmana\nSofort\nNimmt Schattengestalt an, erhöht verursachten Schattenschaden um 40% und verringert erlittenen Nahkampfschaden um 40%. Die Schattengestalt hält an, bis die Aktion abgebrochen wird." }
entries[22919] = { ["name"] = "Gedankenschinden", ["text"] = "60 Mana 20 Meter Reichweite\nKanalisiert (Wirken in 3 sek.)\nFügt bis zu 3 Gegnern Schattenschaden zu und verringert 3 Sek. lang ihr Bewegungstempo." }
entries[22920] = { ["name"] = "Arkanschlag", ["text"] = "Nahkampfreichweite\nSofort\nÜberzieht einen Feind mit Arkanmagie, fügt normalen Schaden plus 24 bis 29 zu und stößt den Feind zurück." }
entries[22921] = { ["name"] = "Gurt der Einsicht", ["text"] = "Wirken in 10 sek.\nReagenzien:\nUnverwüstliches Leder (12), Mächtiges Mojo (12), Geschmeidiger unverwüstlicher Balg (2), Runenfaden (4)\nGurt der Einsicht\nWird beim Anlegen gebunden\nTaille Leder\n142 Rüstung\n+9 Ausdauer\n+23 Intelligenz\nHaltbarkeit 45 / 45\n57" }
entries[22922] = { ["name"] = "Mungostiefel", ["text"] = "Wirken in 10 sek.\nReagenzien:\nUnverwüstliches Leder (12), Essenz der Luft (6), Schwarzer Diamant (4), Geschmeidiger unverwüstlicher Balg (2), Runenfaden (4)\nMungostiefel\nWird beim Anlegen gebunden\nFüße Leder\n174 Rüstung\n+23 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 65 / 65\n57" }
entries[22923] = { ["name"] = "Armschienen der schnellen Flucht", ["text"] = "Wirken in 10 sek.\nReagenzien:\nUnverwüstliches Leder (24), Geschmeidiger unverwüstlicher Balg (6), Runenfaden (4)\nArmschienen der schnellen Flucht\nWird beim Anlegen gebunden\nHandgelenke Kette\n178 Rüstung\n+7 Ausdauer\n+ 41 Distanzangriffskraft\nHaltbarkeit 45 / 45\n57" }
entries[22924] = { ["name"] = "Greifende Ranken", ["text"] = "Wirken in 1 sek.\nFügt nahen Gegnern körperlichen Schaden zu, wirft sie zu Boden und macht sie 10 Sek. lang bewegungsunfähig." }
entries[22926] = { ["name"] = "Chromatischer Umhang", ["text"] = "Wirken in 15 sek.\nReagenzien:\nUnverwüstliches Leder (25), Glänzende chromatische Schuppe (4), Schwarze Drachenschuppe (12), Rote Drachenschuppe (12), Runenfaden (2)\nChromatischer Umhang\nWird beim Anlegen gebunden\nRücken\n105 Rüstung\n+10 Ausdauer\nErhöht Eure kritische Trefferwertung um + 14.\n+9 Feuerwiderstand\n+9 Schattenwiderstand\n57" }
entries[22927] = { ["name"] = "Balg der Wildnis", ["text"] = "Wirken in 15 sek.\nReagenzien:\nUnverwüstliches Leder (30), Wildranke (8), Geschmeidiger unverwüstlicher Balg (2), Runenfaden (2)\nBalg der Wildnis\nWird beim Anlegen gebunden\nRücken\n105 Rüstung\n+17 Ausdauer\n+19 Intelligenz\n57" }
entries[22928] = { ["name"] = "Unbeständiger Umhang", ["text"] = "Wirken in 15 sek.\nReagenzien:\nVerzaubertes Leder (10), Runenfaden\nUnbeständiger Umhang\nWird beim Anlegen gebunden\nRücken\n105 Rüstung\n+17 Beweglichkeit\n+8 Ausdauer\n+ 12 Ausweichen\n57" }
