entries[22937] = { ["name"] = "Giftblitz", ["text"] = "30 Meter Reichweite\nWirken in 2.5 sek.\nSchießt Gift auf den Feind, fügt ihm Naturschaden und dann 10 Sek. lang alle 5 Sek. zusätzlichen Schaden zu." }
